def min_manhattan(cells_a, cells_b):
    """The smallest Manhattan distance between any cell of each set."""
    return min(abs(r - r2) + abs(c - c2) for r, c in cells_a for r2, c2 in cells_b)

def recolor_farthest_duplicate_to_key(grid, key_shape=None):
    """Recolor, to the corner-bar key object's color, the copy farthest from the key among the largest group of same-shaped objects."""
    bg = background(grid)
    multi, singles = find_objects(grid, bg)
    objs = [{'c': grid[r][c], 'cells': comp} for comp in multi + [[p] for p in singles]]
    _, key_norm = normalize_shape(multi[0]) if key_shape is None else (None, key_shape)
    keys = [o for o in objs if is_corner_bar_shape(o['cells'])]
    key = min(keys, key=lambda o: len(o['cells']))
    groups = {}
    for o in objs:
        if o is not key:
            groups.setdefault(normalize_shape(o['cells'])[1], []).append(o)
    dups = [v for v in groups.values() if len(v) > 1]
    grp = max(dups, key=lambda v: len(v[0]['cells']))
    tgt = max(grp, key=lambda o: min_manhattan(o['cells'], key['cells']))
    out = [row[:] for row in grid]
    for r, c in tgt['cells']:
        out[r][c] = key['c']
    return out
